{"component_id":"component-3e12e80b3f3f","code":"def count_powerful_integers(start: int, finish: int, limit: int, s: str) -> int:
    """Count numbers in [start, finish] whose digits are <= limit and end in s."""
    if start > finish or not s or any(int(ch) > limit for ch in s):
        return 0
    suffix_len = len(s)

    def count_prefixes(p: int) -> int:
        if p == 0:
            return 1
        return limit * (limit + 1) ** (p - 1)

    def count_prefix_strictly_less(bound_prefix: str) -> int:
        p = len(bound_prefix)
        if p == 0:
            return 0
        total = 0
        for i, ch in enumerate(bound_prefix):
            digit = ord(ch) - 48
            lo = 1 if i == 0 else 0
            hi = min(limit, digit - 1)
            if hi >= lo:
                total += (hi - lo + 1) * (limit + 1) ** (p - i - 1)
            if digit < lo or digit > limit:
                return total
        return total

    def at_most(bound: int) -> int:
        if bound <= 0:
            return 0
        b = str(bound)
        if any(ord(ch) - 48 > limit for ch in s):
            return 0
        total = 0
        min_len = max(1, suffix_len)
        for length in range(min_len, len(b)):
            total += count_prefixes(length - suffix_len)
        length = len(b)
        if length >= suffix_len:
            p = length - suffix_len
            prefix_bound = b[:p]
            total += count_prefix_strictly_less(prefix_bound)
            if s <= b[p:]:
                if p == 0 or all((ord(ch) - 48) <= limit for ch in prefix_bound) and prefix_bound[0] != '0':
                    total += 1
        return total

    return at_most(finish) - at_most(start - 1)"}
